```go
// Map calls fn on every element of in using at most workers goroutines
// (workers < 1 means 1) and returns the results in input order: out[i] is
// fn(ctx, in[i]).
//
// If any call returns an error, Map stops handing out new inputs, waits for
// running calls to return, and returns a nil slice and an *IndexError for the
// failing input with the LOWEST index among those that failed.
//
// If ctx is cancelled, Map stops handing out new inputs, waits for running
// calls to return, and returns ctx.Err() (unless a call failed first, in which
// case the rule above applies). Map never leaks goroutines: when it returns,
// all workers have exited.
func Map[T, R any](ctx context.Context, in []T, workers int, fn func(context.Context, T) (R, error)) ([]R, error) {
	if workers < 1 {
		workers = 1
	}
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()

	type result struct {
		r   R
		err error
		i   int
	}
	jobs := make(chan int)
	results := make(chan result)
	// sent reports each job the dispatcher handed out, so the collector can
	// tell when every handed-out job has reported back.
	sent := make(chan struct{})
	dispatcherDone := make(chan struct{})

	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				r, err := fn(ctx, in[i])
				results <- result{r: r, err: err, i: i}
			}
		}()
	}
	go func() {
		defer close(jobs)
		defer close(dispatcherDone)
		for i := range in {
			select {
			case <-ctx.Done():
				return
			case jobs <- i:
			}
			sent <- struct{}{}
		}
	}()

	out := make([]R, len(in))
	var first *IndexError
	remaining := 0 // jobs handed out but not yet reported back
	for {
		select {
		case <-sent:
			remaining++
		case res := <-results:
			remaining--
			if res.err != nil {
				if first == nil || res.i < first.Index {
					first = &IndexError{Index: res.i, Err: res.err}
				}
			}
			out[res.i] = res.r
		}
		select {
		case <-dispatcherDone:
			if remaining == 0 {
				goto done
			}
		default:
		}
	}
done:
	wg.Wait() // all workers have exited before we return.
	if first != nil {
		return nil, first
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
return out, nil
}
```

