func Map[T, R any](ctx context.Context, in []T, workers int, fn func(context.Context, T) (R, error)) ([]R, error) {
	if workers < 1 {
		workers = 1
	}
	n := len(in)
	jobs := make(chan int)
	type result struct {
		r   R
		err error
	}
	results := make([]result, n)
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				results[i] = fn(ctx, in[i])
			}
		}()
	}
	for i := range in {
		if ctx.Err() != nil {
			break
		}
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	var first *IndexError
	for i := range in {
		if results[i].err != nil {
			if first == nil || i < first.Index {
				first = &IndexError{Index: i, Err: results[i].err}
			}
			continue
		}
	}
	if first != nil {
		return nil, first
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	out := make([]R, n)
	for i := range in {
		out[i] = results[i].r
	}
	return out, nil
}
